<?php

declare(strict_types=1);

namespace App\Console\Commands;

use App\Models\SeoBacklinkCandidate;
use Illuminate\Console\Command;

final class DeployGeoBacklinks extends Command
{
    protected $signature = 'seo:deploy-geo-backlinks {--dry-run : Sadece kayıt etmeden simüle eder} {--json : JSON rapor sunar}';

    protected $description = '50 yeni Kıbrıs yemek geo-backlink adayı ekler. Hedef anahtar kelimeler: kibris-yemek, kibris-mutfagi.';

    public function handle(): int
    {
        $candidates = $this->getGeoBacklinkCandidates();
        $created = 0;
        $skipped = 0;
        $dryRun = $this->option('dry-run');

        foreach ($candidates as $candidate) {
            $exists = SeoBacklinkCandidate::where('deduplication_hash', $candidate['deduplication_hash'])->exists();

            if ($exists) {
                $skipped++;
                continue;
            }

            if (! $dryRun) {
                $evidence = is_array($candidate['evidence'] ?? null) ? $candidate['evidence'] : [];
                $evidence['domain'] = $candidate['domain'] ?? $candidate['source_host'] ?? null;
                $evidence['topic'] = $candidate['topic'] ?? null;
                $evidence['asset_keyword'] = $candidate['asset_keyword'] ?? null;
                $evidence['authority_score'] = $candidate['authority_score'] ?? 70;
                $evidence['outreach_status'] = $candidate['outreach_status'] ?? 'pending';
                $evidence['pitch_draft_en'] = $candidate['email_template_en'] ?? null;
                $evidence['pitch_draft_tr'] = $candidate['email_template_tr'] ?? null;

                SeoBacklinkCandidate::create([
                    'source_url' => $candidate['source_url'],
                    'source_host' => $candidate['source_host'],
                    'target_url' => $candidate['target_url'],
                    'deduplication_hash' => $candidate['deduplication_hash'],
                    'status' => $candidate['status'] ?? 'candidate',
                    'evidence' => $evidence,
                ]);
            }
            $created++;
        }

        if ($this->option('json')) {
            $this->line((string) json_encode([
                'created' => $created,
                'skipped' => $skipped,
                'total' => count($candidates),
                'dry_run' => $dryRun,
                'geo_keywords' => ['kibris-yemek', 'kibris-mutfagi'],
                'status' => 'success',
            ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));

            return self::SUCCESS;
        }

        $this->info('⚡ Kıbrıs Geo-Backlink Deploy Başlatılıyor...');
        $this->line('  - Toplam aday: '.count($candidates));
        $this->line('  - Oluşturulan: '.$created);
        $this->line('  - Atlanan (var olan): '.$skipped);
        $this->line('  - Mod: '.($dryRun ? '[DRY-RUN]' : '[YAYIN]'));
        $this->info('✓ Kıbrıs yemek geo-backlink adaları başarıyla eklendi.');

        return self::SUCCESS;
    }

